/* An unrolled renderer emits about per_elem bytes per element plus a fixed
   header. Return 1 if n * per_elem + fixed <= 20000, else 0.
   n, per_elem and fixed are >= 0 and each fits in an int, but the product may not. */
int fits(int n, int per_elem, int fixed) {
  return n * per_elem + fixed <= 20000;
}
